import sqlite3

conn = sqlite3.connect('tourism.db')
cursor = conn.cursor()

# Удаляем старые таблицы
cursor.execute('DROP TABLE IF EXISTS places')
cursor.execute('DROP TABLE IF EXISTS last_queries')

# Создаем новую таблицу с координатами маршрутов
cursor.execute('''
    CREATE TABLE places (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        category TEXT NOT NULL,    
        description TEXT,          
        route_points TEXT,         
        route_coords TEXT,         
        price INTEGER NOT NULL,
        rating REAL,               
        time_hours REAL NOT NULL,
        days INTEGER NOT NULL,     
        lat REAL NOT NULL,         
        lon REAL NOT NULL,
        is_excursion BOOLEAN     
    )
''')

cursor.execute('''
    CREATE TABLE last_queries (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        query_text TEXT NOT NULL,
        category TEXT
    )
''')

